// 动态表格渲染服务：按用户指定的字段名渲染表格单元格
const express = require('express');
const ejs = require('ejs');
const app = express();

// 模拟业务数据：每行记录是字段不固定的对象
const records = [
  { id: 1, name: 'alice', role: 'admin' },
  { id: 2, name: 'bob', role: 'guest' }
];

// 外部输入入口：GET /table?field=name，field 由请求者任意指定
app.get('/table', (req, res) => {
  const userField = req.query.field; // 攻击者完全可控，未做任何校验
  const cells = records.map(function (obj) {
    // 将用户输入拼进 EJS 模板源码，再整体编译执行
    const cellTemplate = '<td><%= obj.' + userField + ' %></td>';
    // ejs.render 把 cellTemplate 当作模板源码编译成函数并立即执行
    return ejs.render(cellTemplate, { obj: obj });
  });
  res.send('<table><tr>' + cells.join('') + '</tr></table>');
});

app.listen(3000, () => console.log('listening on 3000'));
```

