import freemarker.template.Configuration;
import freemarker.template.Template;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;

/** 动态报表列渲染：报表列字段名由前端指定，服务端动态拼接取值表达式 */
public class ReportColumnService {

    private final Configuration fmCfg = new Configuration(Configuration.VERSION_2_3_31);

    // userField 来自 HTTP 请求参数 columnField（外部输入入口），期望形如 name/amount
    public String renderColumn(String userField, Map<String, Object> rowData) throws Exception {
        // 将用户输入直接拼进 FreeMarker 模板源码：${obj.字段名}
        String templateSource = "${obj." + userField + "}";
        // 拼接结果被当作模板源码编译，${...} 表达式由 FreeMarker 引擎求值
        Template tpl = new Template("dynCol", new StringReader(templateSource), fmCfg);
        StringWriter out = new StringWriter();
        Map<String, Object> model = new HashMap<>();
        model.put("obj", rowData);
        tpl.process(model, out);
        return out.toString();
    }

    // 模拟请求入口：GET /report/column?columnField=...
    public static void main(String[] args) throws Exception {
        ReportColumnService svc = new ReportColumnService();
        String columnField = args.length > 0 ? args[0] : "name"; // 请求参数直达
        Map<String, Object> row = new HashMap<>();
        row.put("name", "order-1001");
        row.put("amount", 99);
        System.out.println(svc.renderColumn(columnField, row));
    }
}
